SELECT id, customer_id, coupon_codes, items, ARRAY_JOIN(ARRAY_SORT(coupon_codes), ',') AS coupons_text, FORALL(items, x -> x.qty <= 5) AS all_small_qty, EXISTS(items, x -> x.price > 100) AS has_premium_item, TRANSFORM(FILTER(items, x -> x.promo IS NOT NULL), x -> STRUCT(x.product_id AS pid, ROUND(x.price * 0.9, 2) AS discounted_price)) AS promo_lines, SIZE(attributes) AS num_attributes FROM carts
